int cobs_decoder_write(struct cobs_decoder *dec, const uint8_t *buf, size_t len)
{
	int ret = 0;
	size_t i;

	for (i = 0; i < len; ++i) {
		uint8_t byte = buf[i];

		if (dec->code == 0) { /* Expecting a code byte */
			dec->code = byte;
			if (dec->code == 0) {
				return -EINVAL;
			}
			dec->buf_len = 0;
		} else { /* Expecting data bytes */
			if (dec->buf_len < dec->buf_size) {
				dec->buf[dec->buf_len++] = byte;
			} else {
				ret = dec->cb(dec->buf, dec->buf_len, dec->user_data);
				if (ret < 0) {
					return ret;
				}
				dec->buf_len = 0;
				dec->buf[dec->buf_len++] = byte;
			}
		}

		if (dec->code == dec->buf_len + 1) { /* Current block is complete */
			ret = dec->cb(dec->buf, dec->buf_len, dec->user_data);
			if (ret < 0) {
				return ret;
			}
			dec->code = 0; /* Reset for next code byte */
		}
	}

	return len;
}
