int cobs_decoder_write(struct cobs_decoder *dec, const uint8_t *buf, size_t len)
{
	int ret = 0;
	size_t i;

	for (i = 0; i < len; ++i) {
		uint8_t byte = buf[i];

		/* If trailing delimiter is enabled, and we encounter the delimiter byte,
		 * it signifies the end of a frame. Consume it and do not add to decoded data.
		 */
		if ((dec->flags & COBS_FLAG_TRAILING_DELIMITER) && (byte == dec->delimiter)) {
			/* Flush any pending data from the current COBS block before
			 * consuming the delimiter.
			 */
			if (dec->buf_len > 0) {
				ret = dec->cb(dec->buf, dec->buf_len, dec->user_data);
				if (ret < 0) {
					return ret;
				}
				dec->buf_len = 0;
			}

			/* Reset decoder state for the next frame. The actual end-of-frame
			 * signal (cb(NULL, ...)) is expected to be handled by cobs_decoder_close
			 * in the test scenario.
			 */
			dec->code = 0; /* Reset code byte */
			/* dec->buf_len is already 0 */
			continue; /* Skip further processing of this delimiter byte */
		}

		if (dec->code == 0) { /* Expecting a code byte */
			dec->code = byte;
			if (dec->code == 0) {
				return -EINVAL;
			}
			dec->buf_len = 0;
		} else { /* Expecting data bytes */
			if (dec->buf_len < dec->buf_size) {
				dec->buf[dec->buf_len++] = byte;
			} else {
				ret = dec->cb(dec->buf, dec->buf_len, dec->user_data);
				if (ret < 0) {
					return ret;
				}
				dec->buf_len = 0;
				dec->buf[dec->buf_len++] = byte;
			}
		}

		if (dec->code == dec->buf_len + 1) { /* Current block is complete */
			ret = dec->cb(dec->buf, dec->buf_len, dec->user_data);
			if (ret < 0) {
				return ret;
			}
			dec->code = 0; /* Reset for next code byte */
		}
	}

	return len;
}
